#!/usr/bin/env python3
"""Discover helper content files inside the loaded calendar skill directory."""
import os
from pathlib import Path

root = Path(".codex/skills/calendar")
print(f"Searching under: {root.resolve()}")
if not root.exists():
    print("Skill directory not found; searching .codex/skills recursively.")
    root = Path(".codex/skills")

for dirpath, dirnames, filenames in os.walk(root):
    for name in sorted(filenames):
        p = Path(dirpath) / name
        low = name.lower()
        if "helper" in low or "content" in low or "template" in low or "gen" in low:
            print(f"\n=== FILE: {p} ===")
            try:
                print(p.read_text(encoding="utf-8", errors="replace")[:8000])
            except Exception as exc:  # pragma: no cover
                print(f"(unreadable: {exc})")
